import{_,o as e,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2014Q2 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2014Q2 Ceph社区季度进展报告","date":"2014-06-01T00:00:00.000Z","updated":"2014-06-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/2014Q2_Ceph社区季度总结.md","filePath":"posts/2014/2014Q2_Ceph社区季度总结.md","lastUpdated":1780460162000}'),t={name:"posts/2014/2014Q2_Ceph社区季度总结.md"};function o(l,a,s,D,m,n){return e(),r("div",null,[...a[0]||(a[0]=[i('<p>基于提供的23篇会议总结材料，生成2014Q2 Ceph社区季度进展报告如下：</p><hr><h1 id="ceph-社区季度进展报告-·-2014-q2" tabindex="-1">Ceph 社区季度进展报告 · 2014 Q2 <a class="header-anchor" href="#ceph-社区季度进展报告-·-2014-q2" aria-label="Permalink to &quot;Ceph 社区季度进展报告 · 2014 Q2&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度的 Ceph Developer Summit（CDS）集中讨论了以下几个反复出现的核心技术方向：</p><p><strong>OSD 后端与存储引擎演进</strong> OSD 后端架构是本季度讨论最密集的议题。从 FileStore 向新型键值存储后端迁移（RocksDB、Kinetic Drive）的路线图被多次提及，详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_review.html">CDS_G_H_Day_1_-_OSD_review</a>)。</p><p><strong>Erasure Coding 完善</strong> Erasure Coding 插件生态的完善贯穿整个季度，包括本地可修复代码（LRC）提案、ISA 插件原型、ARM 平台性能问题，详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Erasure_Coding_Update.html">CDS_G_H_Day_1_-_Erasure_Coding_Update</a>) 和 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_-_Locally_Repairable_Codes.html">CDS_G_H_Day_1_-<em>OSD</em>-_Locally_Repairable_Codes</a>)。</p><p><strong>RBD 功能扩展</strong> RBD 的异步复制/日志记录、对象索引（object map）、数据库工作负载优化等方向均有专题讨论，详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_RBD_review.html">CDS_G_H_Day_1_-_RBD_review</a>)。</p><p><strong>CI/CD 与测试基础设施</strong> Teuthology 路线图和 CI流程改进是本季度的基础设施重点，详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_CI_Teuthology_Roadmap.html">CDS_G_H_Day_1_-_CI_Teuthology_Roadmap</a>)。</p><p><strong>Calamari 管理平台</strong> Calamari 的功能开发、本地化和部署简化在多个会议中被讨论，详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Calamari_Intro.html">CDS_G_H_Day_1_-_Calamari_Intro</a>) 和 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_Calamari_Localization.html">CDS_G_H_Day_2_-_Calamari_Localization</a>)。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="osd-后端" tabindex="-1">OSD 后端 <a class="header-anchor" href="#osd-后端" aria-label="Permalink to &quot;OSD 后端&quot;">​</a></h3><ul><li><strong>RocksDB 后端</strong>：针对 SD 优化的 RocksDB 键值存储后端开发接近完成，预计很快合并到主分支。相比 LevelDB，RocksDB 在并行压缩和读取方面具有明显性能优势。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_review.html">CDS_G_H_Day_1_-_OSD_review</a>)。</li><li><strong>Kinetic Drive 支持</strong>：探索了对具有以太网接口的 Kinetic Drive 的原生支持，通过 TCP 协议与内置键值数据库交互，整体进展顺利。</li><li><strong>memstore</strong>：内存后端用于基准测试和集群性能验证。</li></ul><h3 id="erasure-coding" tabindex="-1">Erasure Coding <a class="header-anchor" href="#erasure-coding" aria-label="Permalink to &quot;Erasure Coding&quot;">​</a></h3><ul><li><strong>本地可修复代码（LRC）</strong>：提出将数据块映射委托给 EC 插件的方案，通过在 RCode 配置文件中添加 <code>layers</code> 键实现分层编码，可避免跨机架数据传输，节省带宽。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_-_Locally_Repairable_Codes.html">CDS_G_H_Day_1_-<em>OSD</em>-_Locally_Repairable_Codes</a>)。</li><li><strong>ISA 插件</strong>：Andreas 实现了基于 Intel CPU 的 ISA 插件原型，性能优于 Jerasure，正在解决静态库/共享库打包问题。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Erasure_Coding_Update.html">CDS_G_H_Day_1_-_Erasure_Coding_Update</a>)。</li><li><strong>通用 AR 配置文件支持</strong>：提交了 pending PR，支持为 QA、LRC 等不同参数变体定义配置文件。</li></ul><h3 id="rbd" tabindex="-1">RBD <a class="header-anchor" href="#rbd" aria-label="Permalink to &quot;RBD&quot;">​</a></h3><ul><li><strong>异步复制与日志记录</strong>：设计了基于日志文件（通过 Raft 对象条带化存储）的异步复制方案，支持跨数据中心/集群的近实时数据复制，镜像代理架构正在设计中。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_RBD_review.html">CDS_G_H_Day_1_-_RBD_review</a>)。</li><li><strong>对象索引（Object Map）</strong>：引入位图（bitmap）记录 RBD 镜像中对象的存在状态，可加速空间分析、镜像删除、克隆等操作，并讨论了多客户端共享写入场景下的一致性保障。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_RBD_-_Shared_flag_object_map.html">CDS_G_H_Day_2_-<em>RBD</em>-_Shared_flag_object_map</a>)。</li><li><strong>数据库工作负载优化</strong>：针对 PostgreSQL、MySQL 等数据库在 RBD 上的性能问题，讨论了 striping 策略调整、WAL 独立存储、RBD 缓存等优化方案。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_RBD_-_Database_Performance.html">CDS_G_H_Day_2_-<em>RBD</em>-_Database_Performance</a>)。</li><li><strong>RBD discard 功能</strong>：接近完成，仍在进行测试修复。</li></ul><h3 id="cephfs" tabindex="-1">CephFS <a class="header-anchor" href="#cephfs" aria-label="Permalink to &quot;CephFS&quot;">​</a></h3><ul><li><strong>多 CephFS 实例支持</strong>：讨论了在单个 RADOS 集群中运行多个 CephFS 文件系统的两种方案：多 MDS 映射方案和目录语法糖方案，重点关注安全隔离需求。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_CephFS_-_security_multiple_instances_in_a_single_RADOS_cluster.html">CDS_G_H_Day_2_-<em>CephFS</em>-_security_multiple_instances_in_a_single_RADOS_cluster</a>)。</li><li><strong>文件创建与对象级回溯优化</strong>：针对回溯信息（backtrace）写入导致 OSD 负载过重的问题，讨论了异步文件创建和将回溯信息存储至数据池/键值存储的方案。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_CephFS_-_file_creation_object-level_backtraces.html">CDS_G_H_Day_2_-<em>CephFS</em>-_file_creation_object-level_backtraces</a>)。</li></ul><h3 id="rgw" tabindex="-1">RGW <a class="header-anchor" href="#rgw" aria-label="Permalink to &quot;RGW&quot;">​</a></h3><ul><li><strong>Bucket Index 分片扩展</strong>：针对单个 bucket index 对象仅能支持 10-20 RPS 的瓶颈，提出了 bucket index 分片方案，允许在创建 bucket 时指定分片数量，并讨论了无序列表操作以降低系统负载。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_RGW_-_bucket_index_scalability.html">CDS_G_H_Day_2_-<em>RGW</em>-_bucket_index_scalability</a>)。</li></ul><h3 id="monitor" tabindex="-1">Monitor <a class="header-anchor" href="#monitor" aria-label="Permalink to &quot;Monitor&quot;">​</a></h3><ul><li><strong>I/O 异步化</strong>：针对 Monitor 单线程处理消息时 I/O 操作阻塞其他消息的问题，提出将 I/O 操作异步化、引入 Work Queue 工作线程的方案，并讨论了读写锁保护状态信息。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_MON_-_dispatch_messages_while_waiting_for_IO_to_complete.html">CDS_G_H_Day_1_-<em>MON</em>-_dispatch_messages_while_waiting_for_IOto_complete</a>)。</li></ul><h3 id="osd-运维" tabindex="-1">OSD 运维 <a class="header-anchor" href="#osd-运维" aria-label="Permalink to &quot;OSD 运维&quot;">​</a></h3><ul><li><strong>Scrub/Repair 改进</strong>：提出在 Scrub PG 时将不一致性信息记录到 LevelDB，并增加查询和修复接口，支持自动修复策略。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_Repair.html">CDS_G_H_Day_1_-<em>OSD</em>-_Scrub_Repair</a>)。</li><li><strong>Scrub/SnapTrim IO 优先级</strong>：讨论了通过独立线程池、内核 IO 优先级机制和令牌桶机制降低后台任务对客户端 IO 的影响。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.html">CDS_G_H_Day_1_-<em>OSD</em>-_Scrub_SnapTrim_IO_Prioritization</a>)。</li></ul><h3 id="网络与性能" tabindex="-1">网络与性能 <a class="header-anchor" href="#网络与性能" aria-label="Permalink to &quot;网络与性能&quot;">​</a></h3><ul><li><strong>RDMA 更新</strong>：Firefly 升级后性能已恢复至 Emperor 水平并有所提升，讨论了单消息传递器、通道支持和混合协议（IPv4/IPv6）访问方案。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_RDMA_Update.html">CDS_G_H_Day_1_-_RDMA_Update</a>)。</li><li><strong>SystemTap/LTTng 静态追踪点</strong>：两条并行路径同步推进——集成 lttng 和通过 ops 路径收集操作详细信息，目标是将 OSD 中每个 mutex 的获取与操作关联，支持性能瓶颈分析。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_Systemtap_LTTng_static_markers_update.html">CDS_G_H_Day_2_-_Systemtap_LTTng_static_markers_update</a>)。</li></ul><h3 id="构建系统" tabindex="-1">构建系统 <a class="header-anchor" href="#构建系统" aria-label="Permalink to &quot;构建系统&quot;">​</a></h3><ul><li><strong>CMake 迁移</strong>：CMake 构建系统已合并到 Firefly 分支并添加了测试，计划合并到 master 分支，通过减少重复构建对象显著提升多核机器上的构建速度。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_CMake_Update.html">CDS_G_H_Day_1_-_CMake_Update</a>)。</li></ul><h3 id="冷存储" tabindex="-1">冷存储 <a class="header-anchor" href="#冷存储" aria-label="Permalink to &quot;冷存储&quot;">​</a></h3><ul><li><strong>Cold Storage Pools</strong>：讨论了通过 PG 温映射（warm mapping）、PG 强制映射和 Silo 架构实现数据写入后几乎不移动的冷存储池方案，适用于介于磁带和活跃数据之间的存储层。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Cold_Storage_Pools.html">CDS_G_H_Day_1_-_Cold_Storage_Pools</a>)。</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><ul><li><strong>发布周期讨论</strong>：社区对发布节奏进行了深入讨论。过去采用每季度命名版本（两个月编码 + 一个月 QA），Firefly 版本因新功能集成挑战导致时间表延迟。社区正在讨论是否转向定期发布、优先稳定现有功能的策略，该议题将在邮件列表上继续讨论。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_librados_review.html">CDS_G_H_Day_1_-_librados_review</a>)。</li><li><strong>技术领导角色引入</strong>：社区决定引入技术领导（Tech Lead）角色，负责代码审查、优先级排序和项目方向，明确了 Sam Jess、Josh Durkin、Yehuda、Greg 等关键人员的职责。</li><li><strong>CMake 合并到 master</strong>：确认将 CMake 构建系统合并到 master 分支，标志着构建系统现代化的重要里程碑。</li><li><strong>Calamari CRUSH 管理</strong>：将 CRUSH Map 的 CRUD 操作列为高优先级功能，以支持 Erasure Code 池和 Cache Tiering 特性。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Calamari_Development.html">CDS_G_H_Day_1_-_Calamari_Development</a>)。</li><li><strong>librados 内部线程模型改进</strong>：确认推进 librados 内部线程模型更改以提高 IOPS，以及并行读取以减少延迟。</li></ul><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><ul><li><strong>Ceph Developer Summit（CDS）举办</strong>：本季度举办了为期两天的 CDS，涵盖 OSD、RBD、CephFS、RGW、Monitor、Calamari、CI 等几乎所有子系统的专题讨论，参与者包括 Sage、Zach、Josh、Greg、Yehuda 等核心开发者及来自 HGST、IntelYahoo 等公司的贡献者。</li><li><strong>Calamari 本地化</strong>：启动了 Calamari 界面的中文本地化工作，使用 Gettext 工具，由社区成员协作完成界面截图标注和翻译。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_Calamari_Localization.html">CDS_G_H_Day_2_-_Calamari_Localization</a>)。</li><li><strong>Wiki 与社区资源整合</strong>：讨论了 Ceph 社区 Wiki 页面的重建方案，计划整合演讲者信息、事件日历、硬件兼容性指南、路线图、Chum Bucket/Paper Cuts 等资源，并推动学术推广活动。详见 <a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Wiki_IA.html">CDS_G_H_Day_1_-_WikiIA</a>)。</li><li><strong>Google Summer of Code</strong>：Veronica 参与了 GSoC 项目，负责 Erasure Coding 可靠性模型的研究与实现。</li><li><strong>社区参与渠道</strong>：通过邮件列表（ceph-dev、calamari-dev、packaging-maintainers）、IRC（irc.otc.net）和 GitHub PR 进行开发协作，feature tracker 用于工作机会发现和 bug 报告。</li><li><strong>Ink Scope 合作</strong>：讨论了社区项目 Ink Scope 与 Calamari 的合作可能性，鼓励社区成员参与 UI 开发。</li></ul><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2014Q3 将重点推进以下方向：</p><ol><li><strong>RocksDB 后端正式合并</strong>：RocksDB OSD 后端已接近完成，预计将合并到主分支并开始生产验证。</li><li><strong>RBD 异步复制落地</strong>：日志记录机制和镜像代理架构设计完成后，将进入实现阶段，推动跨数据中心复制能力。</li><li><strong>RBD Object Map实现</strong>：位图对象索引方案设计已基本确定，将进入开发和测试阶段。</li><li><strong>Erasure Coding LRC 与 ISA 插件</strong>：本地可修复代码提案和 ISA 插件的打包问题解决后，将推进集成工作。</li><li><strong>RGW Bucket Index 分片</strong>：Duong 将提交分片方案的 PR，推动 RGW 在高并发场景下的扩展能力。</li><li><strong>CephFS 多实例支持</strong>：收集用户用例后，将确定多 CephFS 实例的实现方案并开始开发。</li><li><strong>CI 流程改进</strong>：Teuthology 队列/锁定机制迁移到 Padles 服务，建立类似 Linux Next 的每晚集成分支，引入 Jenkins/Travis CI 自动化测试反馈。</li><li><strong>发布策略确定</strong>：社区将在邮件列表上完成发布周期讨论，确定是否转向定期发布模式。</li><li><strong>Monitor I/O 异步化</strong>：完成代码实现并进行性能测试，评估提升效果。</li><li><strong>Calamari CRUSH 管理功能</strong>：作为高优先级功能，预计将在下季度完成开发并集成到 Calamari REST API。</li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_CI_Teuthology_Roadmap.html">CDS G/H (Day 1) - CI &amp; Teuthology Roadmap</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_CMake_Update.html">CDS G/H (Day 1) - CMake Update</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Calamari_Development.html">CDS G/H (Day 1) - Calamari Development</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Calamari_Intro.html">CDS G/H (Day 1) - Calamari Intro</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Cold_Storage_Pools.html">CDS G/H (Day 1) - Cold Storage Pools</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Erasure_Coding_Update.html">CDS G/H (Day 1) - Erasure Coding Update</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_MON_-_dispatch_messages_while_waiting_for_IO_to_complete.html">CDS G/H (Day 1) - MON: dispatch messages while waiting for IO to complete</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_-_Locally_Repairable_Codes.html">CDS G/H (Day 1) - OSD: Locally Repairable Codes</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_Repair.html">CDS G/H (Day 1) - OSD: Scrub &amp; Repair</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.html">CDS G/H (Day 1) - OSD: Scrub/SnapTrim IO Prioritization</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_OSD_review.html">CDS G/H (Day 1) - OSD review</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_RBD_review.html">CDS G/H (Day 1) - RBD review</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_RDMA_Update.html">CDS G/H (Day 1) - RDMA Update</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_Wiki_IA.html">CDS G/H (Day 1) - Wiki IA</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_1_-_librados_review.html">CDS G/H (Day 1) - librados review</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_Calamari_Localization.html">CDS G/H (Day 2) - Calamari Localization</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_CephFS_-_file_creation_object-level_backtraces.html">CDS G/H (Day 2) - CephFS- file creation &amp; object-level backtraces</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_CephFS_-_security_multiple_instances_in_a_single_RADOS_cluster.html">CDS G/H (Day 2) - CephFS: security &amp; multiple instances in a single RADOS cluster</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_RBD_-_Database_Performance.html">CDS G/H (Day 2) - RBD: Database Performance</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_RBD_-_Shared_flag_object_map.html">CDS G/H (Day 2) - RBD: Shared flag, object map</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_RBD_-_testing_overview_strategy.html">CDS G/H (Day 2) - RBD: testing overview &amp; strategy</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_RGW_-_bucket_index_scalability.html">CDS G/H (Day 2) - RGW: bucket index scalability</a>)</li><li><a href="/VideoSummary/posts/2014/CDS_G_H_Day_2_-_Systemtap_LTTng_static_markers_update.html">CDS G/H (Day 2) - Systemtap/LTTng static markers (update)</a>)</li></ul>',46)])])}const C=_(t,[["render",o]]);export{h as __pageData,C as default};
